import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v
        self.nxt = nxt

def build(vals):
    if not vals:
        return None
    head = N(vals[0])
    cur = head
    for v in vals[1:]:
        cur.nxt = N(v)
        cur = cur.nxt
    return head

def to_list(head):
    res = []
    cur = head
    while cur:
        res.append(str(cur.v))
        cur = cur.nxt
    return ' '.join(res)

def split_list(head, k):
    while head and k > 1:
        head = head.nxt
        k -= 1
    if head is None:
        return None
    rest = head.nxt
    head.nxt = None
    return rest

def merge(a, b, prev):
    while a and b:
        if a.v <= b.v:
            prev.nxt = a
            a = a.nxt
        else:
            prev.nxt = b
            b = b.nxt
        prev = prev.nxt
    prev.nxt = a or b
    while prev.nxt:
        prev = prev.nxt
    return prev

def sort_list(head):
    if head is None or head.nxt is None:
        return head
    n = 0
    cur = head
    while cur:
        n += 1
        cur = cur.nxt
    dummy = N()
    dummy.nxt = head
    step = 1
    while step < n:
        prev = dummy
        cur = dummy.nxt
        while cur:
            left = cur
            right = split_list(left, step)
            cur = split_list(right, step)
            prev = merge(left, right, prev)
        step <<= 1
    return dummy.nxt


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    vals = list(map(int, data[1:1 + n]))
    head = build(vals)
    print(to_list(sort_list(head)))
